### 5. Fail-Closed Authorization Verification Algorithm

The following engine implements complete, fail-closed authorization logic. It uses defensive programming: any missing context, runtime error, or dynamic violation forces an immediate denial.

```typescript
/**
 * Strict Role Enumeration with Absolute Structural Ranks
 */
export enum Role {
  GUEST = 'GUEST',
  MEMBER = 'MEMBER',
  MANAGER = 'MANAGER',
  ADMIN = 'ADMIN',
  OWNER = 'OWNER',
}

export const ROLE_HIERARCHY_WEIGHT: Readonly<Record<Role, number>> = Object.freeze({
  [Role.GUEST]: 1,
  [Role.MEMBER]: 2,
  [Role.MANAGER]: 3,
  [Role.ADMIN]: 4,
  [Role.OWNER]: 5,
});

export interface TenantContext {
  readonly tenantId: string;
}

export interface SecurityPrincipal {
  readonly userId: string;
  readonly tenantId: string;
  readonly role: Role;
  readonly permissions: ReadonlySet<string>;
  readonly securityVersion: number;
}

export interface DatabaseSession {
  query<T>(sql: string, params: unknown[]): Promise<T>;
}

export class AuthorizationSecurityException extends Error {
  constructor(message: string, public readonly incidentCode: string) {
    super(`[AUTH_SEC_VIOLATION] ${incidentCode}: ${message}`);
    this.name = 'AuthorizationSecurityException';
  }
}

/**
 * Production-Grade Fail-Closed Role Mutation Policy Engine
 */
export async function editUserRole(
  actor: SecurityPrincipal,
  targetUserId: string,
  proposedRoleStr: string,
  context: TenantContext,
  db: DatabaseSession
): Promise<void> {
  // -------------------------------------------------------------------------
  // DEFENSIVE BASELINE: Fail-Closed Structural Invariants
  // -------------------------------------------------------------------------
  if (!actor || !targetUserId || !proposedRoleStr || !context) {
    throw new AuthorizationSecurityException(
      'Null or undefined arguments passed to authorization boundary.',
      'SEC_ERR_NULL_CONTEXT'
    );
  }

  // Verify proposed role is a member of the known enum (No Prototype Injection)
  if (!Object.values(Role).includes(proposedRoleStr as Role)) {
    throw new AuthorizationSecurityException(
      `Attempted to assign illegal or unrecognized role: ${proposedRoleStr}`,
      'SEC_ERR_UNKNOWN_ROLE'
    );
  }
  const proposedRole = proposedRoleStr as Role;

  // Invariant 1: Multi-Tenant Scoping Assertion
  if (actor.tenantId !== context.tenantId) {
    throw new AuthorizationSecurityException(
      `Tenant Context Mismatch: Principal (${actor.tenantId}) mutated outside scope (${context.tenantId}).`,
      'SEC_ERR_CROSS_TENANT_BREACH'
    );
  }

  // Invariant 2: Explicit Functional Entitlement Verification
  const REQUIRED_PERMISSION = 'user:edit_role';
  if (!actor.permissions || !actor.permissions.has(REQUIRED_PERMISSION)) {
    throw new AuthorizationSecurityException(
      `Principal lacks fundamental capability: ${REQUIRED_PERMISSION}`,
      'SEC_ERR_MISSING_CAPABILITY'
    );
  }

  // Invariant 3: Anti-Self Modification (Separation of Concerns)
  if (actor.userId === targetUserId) {
    throw new AuthorizationSecurityException(
      'Execution denied: Actors are strictly forbidden from mutating their own role.',
      'SEC_ERR_SELF_MUTATION'
    );
  }

  // Invariant 4: Hierarchical Ceiling Invariant on Proposed Role
  const actorWeight = ROLE_HIERARCHY_WEIGHT[actor.role] ?? 0;
  const proposedWeight = ROLE_HIERARCHY_WEIGHT[proposedRole] ?? Number.MAX_SAFE_INTEGER;

  // The actor's rank MUST be strictly greater than the role they are attempting to grant.
  // Prevents horizontal duplication (Admin creating Admin) and vertical escalation (Admin creating Owner).
  if (actorWeight <= proposedWeight) {
    throw new AuthorizationSecurityException(
      `Privilege Ceiling Exceeded: Actor rank (${actor.role}) cannot provision role (${proposedRole}).`,
      'SEC_ERR_CEILING_VIOLATION'
    );
  }

  // -------------------------------------------------------------------------
  // PERSISTENCE & CONCURRENCY: Locked Target Fetch (Pessimistic Locking)
  // -------------------------------------------------------------------------
  // Query locks the row to guarantee serializability and eliminate TOCTOU race conditions.
  const targetRows = await db.query<Array<{ user_id: string; tenant_id: string; role: Role }>>(
    `SELECT user_id, tenant_id, role 
     FROM organization_memberships 
     WHERE user_id = $1 AND tenant_id = $2 
     FOR UPDATE`,
    [targetUserId, context.tenantId]
  );

  if (!targetRows || targetRows.length === 0) {
    // Fail closed: Do not disclose existence of target user outside tenant boundary
    throw new AuthorizationSecurityException(
      'Target user not found within the boundaries of this tenant.',
      'SEC_ERR_TARGET_NOT_FOUND'
    );
  }

  const target = targetRows[0];

  // Invariant 5: Double-Check Target Tenant Confinement
  if (target.tenant_id !== context.tenantId) {
    throw new AuthorizationSecurityException(
      'Data layer integrity error: Target user tenant misaligned with execution context.',
      'SEC_ERR_DATA_CORRUPTION'
    );
  }

  // Invariant 6: Hierarchical Superiority Invariant over Target's Current State
  const targetCurrentWeight = ROLE_HIERARCHY_WEIGHT[target.role];
  if (targetCurrentWeight === undefined) {
    throw new AuthorizationSecurityException(
      'Target user possesses a corrupted or unranked internal state.',
      'SEC_ERR_CORRUPT_TARGET_STATE'
    );
  }

  // The actor's rank MUST be strictly greater than the target's CURRENT role.
  // Prevents an Admin from touching an Owner, or an Admin from modifying another Admin.
  if (actorWeight <= targetCurrentWeight) {
    throw new AuthorizationSecurityException(
      `Dominance Violation: Actor rank (${actor.role}) is lower than or equal to target's current rank (${target.role}).`,
      'SEC_ERR_HIERARCHY_VIOLATION'
    );
  }

  // Invariant 7: Target Liveness & Minimum Cardinality
  if (target.role === Role.OWNER) {
    // Safety check: Although Invariant 6 blocks non-Owners from touching an Owner,
    // this secondary assertion guards the Owner transfer/demotion flow against leaving the org ownerless.
    const countResult = await db.query<Array<{ count: string }>>(
      `SELECT count(*) as count 
       FROM organization_memberships 
       WHERE tenant_id = $1 AND role = 'OWNER'`,
      [context.tenantId]
    );

    const ownerCount = parseInt(countResult[0]?.count ?? '0', 10);
    if (ownerCount <= 1) {
      throw new AuthorizationSecurityException(
        'Cardinality Panic: Cannot demote the sole remaining Owner of this organization.',
        'SEC_ERR_LAST_OWNER_ORPHANAGE'
      );
    }
  }

  // -------------------------------------------------------------------------
  // EXECUTION: Atomic Mutation and Invalidation
  // -------------------------------------------------------------------------
  try {
    // 1. Mutate the role and increment security_version atomically
    await db.query(
      `UPDATE organization_memberships 
       SET role = $1, security_version = security_version + 1, updated_at = NOW() 
       WHERE user_id = $2 AND tenant_id = $3`,
      [proposedRole, targetUserId, context.tenantId]
    );

    // 2. Cascade hard revocation to active refresh tokens
    await db.query(
      `DELETE FROM oauth_refresh_tokens 
       WHERE user_id = $1 AND tenant_id = $2`,
      [targetUserId, context.tenantId]
    );

    // Transaction concludes successfully downstream.
  } catch (err: unknown) {
    // Fail-Closed: Log technical details securely, rethrow generic secure runtime error
    throw new AuthorizationSecurityException(
      'Internal persistence error during role state mutation.',
      'SEC_ERR_INTERNAL_FAULT'
    );
  }
}
```

